#!/usr/bin/env python3
"""Regenerate the project-root .clangd from build/compile_commands.json.

Companion to gen_cpp_props.py, which does the same job for the Microsoft C/C++
extension. This one targets clangd.

Why this exists: headers are not in compile_commands.json, so clangd infers a
header's flags from the "closest" entry by path. Only 3 of the ~749 entries in
this project are our own translation units -- the rest are CMSIS-DSP and SDK
files -- so a header in inc/ almost always inherits flags from a file that has
no -I for our include tree and none of the Pico SDK's -isystem paths. The result
is a cascade of bogus "file not found" errors on headers that plainly exist.

Baking the real include dirs into .clangd via CompileFlags.Add makes header
parsing independent of whichever entry the inference lands on.

Also note the two things this file must NOT do:

  * Do not add `--target=arm-none-eabi`. clangd passes these flags to the real
    compiler when --query-driver extracts system include paths, and GCC rejects
    `--target=` outright (exit 1). That kills the driver query, so clangd never
    learns where libstdc++ lives and every file fails on <cassert>.
    --query-driver supplies both the target and the include paths already.

  * Do not let clangd find the stale in-source compile_commands.json at the
    project root -- hence CompilationDatabase: build. That older database was
    generated with a different toolchain whose path cannot match the
    --query-driver glob in .vscode/settings.json.

Run after any CMake reconfigure that changes include dirs, then run
"clangd: Restart language server" from the command palette.
"""
import json
import os
import re

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
db_path = os.path.join(root, "build", "compile_commands.json")
db = json.load(open(db_path, encoding="utf8"))


def is_main(entry):
    f = entry["file"].replace("\\", "/")
    return f.endswith("src/main.cpp") and "weather/src" in f


entry = next(e for e in db if is_main(e))
cmd = (entry.get("command") or " ".join(entry.get("arguments", []))).replace("\\", "/")

# Both joined (-Ifoo) and separated (-I foo) forms appear in CMake output.
includes = []
for flag in ("-I", "-isystem"):
    pattern = re.compile(r'%s\s*"?([^"\s]+)"?' % re.escape(flag))
    for path in pattern.findall(cmd):
        item = "%s%s" % (flag, path)
        if item not in includes:
            includes.append(item)

header = '''# GENERATED by .vscode/gen_clangd.py -- edit that script, not this file.
#
# Header parsing needs the real include dirs: headers are absent from
# compile_commands.json, and only 3 of its ~%d entries are our own translation
# units, so clangd's path-proximity inference otherwise hands a header the flags
# of some CMSIS-DSP file with no -I for our tree.
#
# Do NOT add --target=arm-none-eabi here: clangd feeds these same flags to the
# real compiler for --query-driver system-include extraction, and GCC exits 1 on
# an unrecognised --target=, which breaks <cassert> resolution everywhere.
# --query-driver (see .vscode/settings.json) supplies the target already.
#
# CompilationDatabase pins clangd to build/ so it ignores the stale in-source
# database at the project root, which was generated with a different toolchain.
CompileFlags:
  CompilationDatabase: build
  Remove: [-mfp16-format*, -march*]
  Add:
''' % len(db)

body = "".join("    - %s\n" % inc for inc in includes)

# CMSIS ships both cmsis_gcc.h and cmsis_clang.h and picks between them on
# __GNUC__ / __clang__. The real build uses GCC, takes the cmsis_gcc.h path, and
# compiles clean. clangd is clang, so it takes cmsis_clang.h -- which expects
# __nop to be a compiler builtin -- and that collides with the Pico SDK's own
# `__force_inline static void __nop(void)` in hardware/sync.h. The result is
# "redefinition of '__nop'" on every file that pulls in both trees, i.e. most of
# them. It is purely an artefact of clangd not being the compiler this project
# builds with.
#
# Cost of this suppression: genuine redefinition errors are hidden in the
# editor too. They still fail the actual build, which is the authority.
body += """
Diagnostics:
  Suppress:
    - redefinition
"""

out_path = os.path.join(root, ".clangd")
with open(out_path, "w", encoding="utf8", newline="\n") as fh:
    fh.write(header + body)

print("wrote %s with %d include dirs" % (out_path, len(includes)))
